-- Requirements 14-20 upgrade (run once on an existing SGCS database after backup).
CREATE TABLE IF NOT EXISTS schools (school_id INT AUTO_INCREMENT PRIMARY KEY, school_name VARCHAR(100) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS institutes (institute_id INT AUTO_INCREMENT PRIMARY KEY, school_id INT NOT NULL, institute_name VARCHAR(100) NOT NULL, UNIQUE KEY uq_institute_school_name (school_id,institute_name), FOREIGN KEY (school_id) REFERENCES schools(school_id));
CREATE TABLE IF NOT EXISTS programmes (programme_id INT AUTO_INCREMENT PRIMARY KEY, institute_id INT NOT NULL, programme_name VARCHAR(100) NOT NULL, UNIQUE KEY uq_programme_institute_name (institute_id,programme_name), FOREIGN KEY (institute_id) REFERENCES institutes(institute_id));
CREATE TABLE IF NOT EXISTS graduation_sets (graduation_set_id INT AUTO_INCREMENT PRIMARY KEY, set_name VARCHAR(100) NOT NULL UNIQUE, graduation_year YEAR NOT NULL, is_active TINYINT(1) NOT NULL DEFAULT 0, starts_at DATETIME NULL, ends_at DATETIME NULL);
ALTER TABLE students ADD COLUMN first_name VARCHAR(60) NULL, ADD COLUMN middle_name VARCHAR(60) NULL, ADD COLUMN last_name VARCHAR(60) NULL, ADD COLUMN school_id INT NULL, ADD COLUMN institute_id INT NULL, ADD COLUMN programme_id INT NULL, ADD COLUMN graduation_set_id INT NULL, ADD COLUMN certificate_name_order ENUM('first_middle_last','last_first_middle') NULL, ADD COLUMN certificate_name_confirmed_at DATETIME NULL, ADD CONSTRAINT fk_students_school FOREIGN KEY (school_id) REFERENCES schools(school_id), ADD CONSTRAINT fk_students_institute FOREIGN KEY (institute_id) REFERENCES institutes(institute_id), ADD CONSTRAINT fk_students_programme FOREIGN KEY (programme_id) REFERENCES programmes(programme_id), ADD CONSTRAINT fk_students_grad_set FOREIGN KEY (graduation_set_id) REFERENCES graduation_sets(graduation_set_id);
ALTER TABLE clearance_requests ADD COLUMN graduation_set_id INT NULL, ADD CONSTRAINT fk_clearance_grad_set FOREIGN KEY (graduation_set_id) REFERENCES graduation_sets(graduation_set_id), ADD KEY idx_clearance_student_set_status (student_id,graduation_set_id,overall_status);
ALTER TABLE supporting_documents MODIFY request_id INT NULL, MODIFY document_type ENUM('id_passport','final_year_project','fee_statement') NOT NULL, ADD COLUMN stored_name VARCHAR(255) NOT NULL DEFAULT '', ADD COLUMN mime_type VARCHAR(100) NOT NULL DEFAULT 'application/pdf', ADD COLUMN status ENUM('Pending','Approved','Rejected','Replaced') NOT NULL DEFAULT 'Pending', ADD COLUMN replaced_at DATETIME NULL, ADD KEY idx_document_student_type_status (student_id,document_type,status);
